export type OrganizationType =
  | 'government_accredited_auditor'
  | 'bank_incentives_partner'
  | 'verification_agency'
  | 'other';

export interface AdminPortalUser {
  _id?: string;
  email?: string;
  role?: 'admin' | 'view' | string;
  profile?: {
    firstName?: string;
    lastName?: string;
    phone?: string;
  };
  accessCredentials?: {
    organizationType?: OrganizationType;
    organizationName?: string;
    credentialId?: string;
    accessPurpose?: string;
  };
}

export const formatOrganizationType = (value?: OrganizationType | string): string => {
  switch (value) {
    case 'government_accredited_auditor':
      return 'Government accredited auditor';
    case 'bank_incentives_partner':
      return 'Bank (incentives partner)';
    case 'verification_agency':
      return 'Verification agency';
    case 'other':
      return 'Other';
    default:
      return 'Credentialed reviewer';
  }
};

export const getPortalRoleLabel = (role?: string): string => {
  if (role === 'admin') {
    return 'Platform administrator';
  }
  if (role === 'view') {
    return 'Credentialed reviewer';
  }
  if (role === 'support') {
    return 'Customer support';
  }
  return 'Portal user';
};
